/**
 * Active members of this workspace, with the email address on their account.
 * Removed (archived) and non-active members are excluded so callers can match
 * an address without assigning work to someone who is no longer here.
 */
export async function listActiveMemberEmails(
  orgId: OrgId,
): Promise<readonly { readonly userId: UserId; readonly email: string }[]> {
  const rows = getDb()
    .select({ userId: users.id, email: users.email })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .all();

  return rows.map((row) => ({
    userId: brandId<UserId>(row.userId),
    email: row.email,
  }));
