/**
 * Persisted bulk-import keys and the issue rows they created.
 *
 * The key is unique per workspace. A second upload of the same key reads this
 * row back instead of inserting again, including after a process restart.
 */
import { and, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  getDb,
  issueImports,
  issueLabels,
  issues,
  labels,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId } from "./_mappers";
import type { ImportIssueRowInput } from "@/schemas/issue-import";
import type { IssueId, LabelId, OrgId, ProjectId, UserId } from "@/types/common";
import type { IssuePriority, IssueStatus } from "@/types/issue";

const DEFAULT_LABEL_COLOR = "#94a3b8";

export interface StoredIssueImport {
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
}

export interface ImportIssueWrite {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly dueAt: ImportIssueRowInput["dueAt"];
  readonly assigneeId: UserId | null;
  readonly labels: readonly string[];
}

export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<StoredIssueImport | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();

  if (!row) return null;

  const parsed = JSON.parse(row.issueIds) as readonly string[];
  return {
    projectId: brandId<ProjectId>(row.projectId),
    issueIds: parsed.map((id) => brandId<IssueId>(id)),
  };
}

/**
 * Inserts every issue, any labels that did not yet exist, and the import key
 * in one transaction. Nothing is left behind when a statement fails.
 * Numbers continue after the highest number the project has ever used.
 */
export async function insertIssueImport(input: {
  orgId: OrgId;
  projectId: ProjectId;
  importKey: string;
  authorId: UserId;
  rows: readonly ImportIssueWrite[];
}): Promise<readonly IssueId[]> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const existingLabels = tx
      .select()
      .from(labels)
      .where(orgPredicate(labels.orgId, input.orgId))
      .all();

    const labelIdByName = new Map<string, LabelId>();
    for (const label of existingLabels) {
      labelIdByName.set(label.name, brandId<LabelId>(label.id));
    }

    const missingNames = new Set<string>();
    for (const row of input.rows) {
      for (const name of row.labels) {
        if (!labelIdByName.has(name)) missingNames.add(name);
      }
    }

    for (const name of missingNames) {
      const id = newId();
      tx.insert(labels)
        .values({
          id,
          orgId: input.orgId,
          name,
          color: DEFAULT_LABEL_COLOR,
          description: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();
      labelIdByName.set(name, brandId<LabelId>(id));
    }

    const maxRow = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, input.orgId),
          eq(issues.projectId, input.projectId),
        ),
      )
      .get();
    let number = (maxRow?.value ?? 0) + 1;

    const issueIds: IssueId[] = [];

    for (const row of input.rows) {
      const seen = new Set<string>();
      const labelIds: LabelId[] = [];
      for (const name of row.labels) {
        if (seen.has(name)) continue;
        seen.add(name);
        const labelId = labelIdByName.get(name);
        if (labelId !== undefined) labelIds.push(labelId);
      }

      const id = newId();
      tx.insert(issues)
        .values({
          id,
          orgId: input.orgId,
          projectId: input.projectId,
          number,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: input.authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId: id,
              labelId,
            })),
          )
          .run();
      }

      issueIds.push(brandId<IssueId>(id));
      number += 1;
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        projectId: input.projectId,
        importKey: input.importKey,
        issueIds: JSON.stringify(issueIds),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return issueIds;
  });
}

