/**
 * Turns every row of an upload into an issue, in file order.
 *
 * The batch is refused before any write when the actor cannot create an issue
 * here, the project is missing or archived, the plan quota cannot hold every
 * row, or the issue-creation rate allowance cannot cover one token per row.
 * A refused upload does not keep its key. The same key in this workspace
 * returns the original issues and publishes nothing.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const existing = await issueImportRepo.findIssueImport(
    input.orgId,
    input.importKey,
  );
  if (existing) {
    return {
      importKey: input.importKey,
      projectId: existing.projectId,
      issues: await loadIssuesInOrder(input.orgId, existing.issueIds),
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const assigneeByEmail = new Map<string, UserId>();
  for (const member of await memberRepo.listActiveMemberEmails(input.orgId)) {
    assigneeByEmail.set(member.email.toLowerCase(), member.userId);
  }

  let issueIds: readonly IssueId[];
  try {
    issueIds = await issueImportRepo.insertIssueImport({
      orgId: input.orgId,
      projectId: input.projectId,
      importKey: input.importKey,
      authorId: actor.userId,
      rows: input.rows.map((row) => ({
        title: row.title,
        description: row.description ?? null,
        status: row.status ?? "backlog",
        priority: row.priority ?? "none",
        dueAt: row.dueAt ?? null,
        assigneeId: resolveAssignee(assigneeByEmail, row.assigneeEmail),
        labels: row.labels ?? [],
      })),
    });
  } catch (error) {
    const raced = await issueImportRepo.findIssueImport(
      input.orgId,
      input.importKey,
    );
    if (!raced) throw error;
    return {
      importKey: input.importKey,
      projectId: raced.projectId,
      issues: await loadIssuesInOrder(input.orgId, raced.issueIds),
      replayed: true,
    };
  }

  const issues = await loadIssuesInOrder(input.orgId, issueIds);

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: project.id,
    importKey: input.importKey,
    issueIds: issues.map((issue) => issue.id),
  });

  return {
    importKey: input.importKey,
    projectId: project.id,
    issues,
    replayed: false,
  };
}

function resolveAssignee(
  assigneeByEmail: ReadonlyMap<string, UserId>,
  assigneeEmail: string | null | undefined,
): UserId | null {
  if (assigneeEmail === null || assigneeEmail === undefined) return null;
  return assigneeByEmail.get(assigneeEmail.toLowerCase()) ?? null;
}

async function loadIssuesInOrder(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<Issue[]> {
  const loaded: Issue[] = [];
  for (const issueId of issueIds) {
    loaded.push(
      requireFound(
        await issueRepo.findIssueById(orgId, issueId),
        "Issue",
        issueId,
      ),
    );
  }
  return loaded;
}

