import { eq } from "drizzle-orm";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { importIssuesSchema } from "@/schemas/issue-import";
import { getDb, webhookDeliveries } from "@/server/db";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import { importIssues } from "@/server/services/issue-service";
import { createIssue } from "@/server/services/issue-service";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { PermissionDeniedError } from "@/lib/permissions";
import { NotFoundError } from "@/server/services/_support";
import { resetRateLimits, setOrgPlan } from "@/lib/rate-limit";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("import", "free");
  registerEventHandlers();
  resetRateLimits();
  setOrgPlan(tenant.org.id, "free");
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

describe("importIssues", () => {
  it("imports rows in order and replays the key", async () => {
    const input = importIssuesSchema.parse({
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      importKey: "upload-key-1",
      rows: [
        {
          title: "First imported",
          description: "alpha",
          status: "todo",
          priority: "high",
          assigneeEmail: "MEMBER@import.test",
          labels: ["bug", "bug", "Sprint"],
          dueAt: "2026-04-01T00:00:00.000Z",
        },
        {
          title: "Second imported",
          labels: ["bug", "chore"],
          assigneeEmail: "nobody@example.com",
        },
      ],
    });

    const created = await importIssues(tenant.actors.member, input);
    expect(created.replayed).toBe(false);
    expect(created.issues.map((issue) => issue.number)).toEqual([1, 2]);
    expect(created.issues[0]).toMatchObject({
      title: "First imported",
      description: "alpha",
      status: "todo",
      priority: "high",
      authorId: tenant.actors.member.userId,
      assigneeId: tenant.userIds.member,
      parentId: null,
      estimate: null,
      dueAt: "2026-04-01T00:00:00.000Z",
    });
    expect(created.issues[1]).toMatchObject({
      title: "Second imported",
      assigneeId: null,
      status: "backlog",
      priority: "none",
      description: null,
    });

    const labels = await labelRepo.listLabels(tenant.org.id);
    const byName = new Map(labels.map((label) => [label.name, label]));
    expect(byName.size).toBe(3);
    expect(byName.get("bug")).toMatchObject({ color: "#94a3b8", description: null });
    expect(created.issues[0]?.labelIds).toEqual([
      byName.get("bug")?.id,
      byName.get("Sprint")?.id,
    ]);
    expect(created.issues[1]?.labelIds).toEqual([
      byName.get("bug")?.id,
      byName.get("chore")?.id,
    ]);

    const replay = await importIssues(
      tenant.actors.member,
      importIssuesSchema.parse({
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        importKey: "upload-key-1",
        rows: [{ title: "Different title now" }],
      }),
    );
    expect(replay.replayed).toBe(true);
    expect(replay.issues.map((issue) => issue.id)).toEqual(
      created.issues.map((issue) => issue.id),
    );
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(2);

    const activity = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["issues.imported"],
      limit: 25,
      cursor: null,
    });
    expect(activity.items).toHaveLength(1);
    expect(activity.items[0]).toMatchObject({
      action: "issues.imported",
      actorId: tenant.actors.member.userId,
      subjectKind: "project",
      subjectId: tenant.project.id,
      projectId: tenant.project.id,
      metadata: { count: 2, importKey: "upload-key-1" },
    });
    const createdAudit = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["issue.created"],
      limit: 25,
      cursor: null,
    });
    expect(createdAudit.items).toHaveLength(0);

    const usage = await usageRepo.recomputeUsage(tenant.org.id);
    const cached = await usageRepo.getUsage(tenant.org.id);
    expect(cached.issuesUsed).toBe(2);
    expect(usage.issuesUsed).toBe(2);

    const indexed = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "alpha",
      limit: 10,
      cursor: null,
    });
    expect(indexed.total).toBe(1);

    const notes = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      limit: 25,
      cursor: null,
    });
    expect(notes.items).toHaveLength(0);

    const deliveries = getDb()
      .select()
      .from(webhookDeliveries)
      .where(eq(webhookDeliveries.orgId, tenant.org.id))
      .all();
    expect(deliveries).toHaveLength(0);

    const next = await createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "After the import" }),
    );
    expect(next.number).toBe(3);
  });

  it("refuses the batch without keeping the key when over quota", async () => {
    const quotaTenant = await createTenant("importquota", "free");
    setOrgPlan(quotaTenant.org.id, "free");
    for (let number = 1; number <= 99; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quotaTenant.org.id, quotaTenant.project.id, {
          title: `Seed issue ${number}`,
        }),
        quotaTenant.actors.member.userId,
        number,
      );
    }

    await expect(
      importIssues(
        quotaTenant.actors.member,
        importIssuesSchema.parse({
          orgId: quotaTenant.org.id,
          projectId: quotaTenant.project.id,
          importKey: "quota-key-01",
          rows: [{ title: "One fits" }, { title: "Two does not" }],
        }),
      ),
    ).rejects.toThrow(/allows no more issues/);

    expect(
      await issueRepo.countIssues(quotaTenant.org.id, quotaTenant.project.id),
    ).toBe(99);

    const retry = await importIssues(
      quotaTenant.actors.member,
      importIssuesSchema.parse({
        orgId: quotaTenant.org.id,
        projectId: quotaTenant.project.id,
        importKey: "quota-key-01",
        rows: [{ title: "Just one" }],
      }),
    );
    expect(retry.replayed).toBe(false);
    expect(retry.issues).toHaveLength(1);
    expect(retry.issues[0]?.number).toBe(100);
  });

  it("refuses when the rate allowance cannot cover the batch", async () => {
    resetRateLimits();
    setOrgPlan(tenant.org.id, "free");
    await expect(
      importIssues(
        tenant.actors.member,
        importIssuesSchema.parse({
          orgId: tenant.org.id,
          projectId: tenant.project.id,
          importKey: "rate-key-001",
          rows: Array.from({ length: 61 }, (_, index) => ({
            title: `Rate row ${index + 10}`,
          })),
        }),
      ),
    ).rejects.toThrow(/rate limit/);
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(3);
  });

  it("rejects viewers, other orgs, missing projects and archived projects", async () => {
    const base = {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      importKey: "access-key-1",
      rows: [{ title: "Should not land" }],
    };
    await expect(
      importIssues(tenant.actors.viewer, importIssuesSchema.parse(base)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      importIssues(
        { ...tenant.actors.member, orgId: tenant.userIds.owner },
        importIssuesSchema.parse({
          ...base,
          orgId: tenant.userIds.owner,
        }),
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      importIssues(
        tenant.actors.member,
        importIssuesSchema.parse({
          ...base,
          projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP",
        }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    const archivedTenant = await createTenant("importarch", "free");
    await projectRepo.archiveProject(archivedTenant.org.id, archivedTenant.project.id);
    await expect(
      importIssues(
        archivedTenant.actors.member,
        importIssuesSchema.parse({
          orgId: archivedTenant.org.id,
          projectId: archivedTenant.project.id,
          importKey: "archived-key",
          rows: [{ title: "No archive import" }],
        }),
      ),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    expect(await memberRepo.countActiveMembers(tenant.org.id)).toBeGreaterThan(0);
    expect(await webhookRepo.countEndpoints(tenant.org.id)).toBe(0);
  });
});

